from sales_dashboard.loader import parse_session_log
from sales_dashboard.metrics import conversion_rate, pooled_conversion_rate
from sales_dashboard.report import campaign_summary
from sales_dashboard.loader import dedupe_sessions, daily_conversion_counts
from sales_dashboard.metrics import conversions_in_window, conversion_rate_by_group, longest_conversion_streak
from sales_dashboard.report import top_converting_groups


def test_conversion_rate_basic():
    assert conversion_rate([{"converted": True}, {"converted": False}]) == 0.5


def test_conversion_rate_none_counts_as_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5


def test_pooled_conversion_rate_equal_groups():
    groups = {"a": [{"converted": True}, {"converted": False}], "b": [{"converted": True}, {"converted": False}]}
    assert pooled_conversion_rate(groups) == 0.5


def test_parse_session_log_one_line():
    assert parse_session_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "converted": True}]


def test_campaign_summary_basic():
    e = [{"id": "a", "day": 1, "converted": True}, {"id": "b", "day": 2, "converted": False}]
    assert campaign_summary({"g": e}, 1)["groups"] == 1


def test_dedupe_sessions_keeps_last_record_for_duplicate_id():
    events = [
        {"id": "same", "day": 1, "converted": True},
        {"id": "other", "day": 2, "converted": False},
        {"id": "same", "day": 3, "converted": False},
    ]
    assert dedupe_sessions(events) == [
        {"id": "other", "day": 2, "converted": False},
        {"id": "same", "day": 3, "converted": False},
    ]


def test_parse_session_log_blank_comments_whitespace_and_none():
    assert parse_session_log([
        "  # comment",
        "   ",
        " x1 , 3 , 1 ",
        "x2,4,0",
        "x3,5,",
    ]) == [
        {"id": "x1", "day": 3, "converted": True},
        {"id": "x2", "day": 4, "converted": False},
        {"id": "x3", "day": 5, "converted": None},
    ]


def test_parse_session_log_errors_include_original_line_number():
    import pytest

    with pytest.raises(ValueError, match="line 3"):
        parse_session_log(["", " # skipped", "id,not-a-day,1"])


def test_pooled_conversion_rate_is_weighted_by_sessions():
    groups = {
        "large": [{"converted": True}] + [{"converted": False}] * 9,
        "small": [{"converted": True}],
    }
    assert pooled_conversion_rate(groups) == 2 / 11
    assert pooled_conversion_rate({"empty": []}) == 0.0


def test_window_counts_exact_number_of_days_including_zero():
    assert conversions_in_window([1, 2, 3], 2) == 5
    assert conversions_in_window([1, 2, 3], 0) == 0
    assert conversions_in_window([1, 2, 3], 5) == 6


def test_daily_counts_are_inclusive_zero_filled_and_range_limited():
    events = [
        {"day": 0, "converted": True},
        {"day": 2, "converted": True},
        {"day": 2, "converted": None},
        {"day": 4, "converted": True},
    ]
    assert daily_conversion_counts(events, 1, 3) == [0, 1, 0]
    assert daily_conversion_counts(events, 4, 3) == []


def test_campaign_summary_rounds_to_three_places_and_counts_active_groups():
    groups = {
        "active": [{"day": 1, "converted": True}, {"day": 1, "converted": False}, {"day": 2, "converted": False}],
        "inactive": [],
    }
    assert campaign_summary(groups, 1) == {"rate": 0.333, "recent": 0, "groups": 1}


def test_group_rates_and_top_groups_follow_spec_ordering():
    groups = {
        "z": [{"converted": True}],
        "b": [{"converted": True}],
        "a": [],
    }
    assert list(conversion_rate_by_group(groups)) == ["a", "b", "z"]
    assert conversion_rate_by_group(groups)["a"] is None
    assert top_converting_groups(groups, 2) == ["b", "z"]


def test_longest_streak_requires_positive_counts():
    assert longest_conversion_streak([1, 2, 0, -1, 4, 5]) == 2
    assert longest_conversion_streak([]) == 0


def test_package_exports_spec_api():
    import sales_dashboard

    assert callable(sales_dashboard.daily_conversion_counts)
    assert callable(sales_dashboard.conversion_rate)

